			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(ad.FieldCreatedAt)
			}
			if _, exists := b.mutation.AccountID(); exists {
				s.SetIgnore(ad.FieldAccountID)
			}
			if _, exists := b.mutation.CampaignID(); exists {
				s.SetIgnore(ad.FieldCampaignID)
			}
			if _, exists := b.mutation.AdGroupID(); exists {
				s.SetIgnore(ad.FieldAdGroupID)
			}
